INSERT INTO `categories_details` VALUES (1,'**ESTO ES ACERCA DE**\n\n***aaaaa***',NULL,NULL,NULL,NULL,NULL,8,1),(2,'La revista **Teoría y Praxis** es una publicación semestral de la Facultad de Ciencias y Humanidades de la Universidad Don Bosco de El Salvador. El objetivo de la revista es promover y difundir la publicación de textos científicos críticos e inéditos en el campo de los conocimientos sociales y humanos sobre problemáticas nacionales e internacionales. El contenido de la revista está dirigido a especialistas, investigadores y estudiantes de pregrado y postgrado.\n\n**Teoría y Praxis** recoge los empeños intelectuales de catedráticos y colaboradores de la Universidad Don Bosco. Este esfuerzo quiere ser la simbiosis entre la razón y la realidad, entre lo intelectual y lo integral, y, en definitiva entre la teoría y la praxis. Así, este empeño manifiesta que nuestros esfuerzos teóricos no deben estar lejanos de la realidad y, viceversa, que nuestros esfuerzos prácticos no deben naufragar en los océanos del activismo y del esquematismo pragmático. En este sentido, la teoría es un momento de la práctica, y la práctica es un momento de la teoría. En conclusión, **Teoría y Praxis** es el desafío permanente a nuestra razón y el desafío asintótico de nuestra esperanza, lo cual nos hace crecer en la medida que ofrezcamos ejercicios teóricos y prácticos a la sociedad que, con tanta premura, nos demanda respuestas consistentes a sus problemas más acuciantes. (1)\n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |\n\n   **(1) Universidad Don Bosco (2002). Editorial Teoría y Praxis núm. 1, 3.**','El **Consejo Editorial** de **Teoría y Praxis** está integrado por:\n\n* José Humberto Flores Muñoz, Director, Doctor en Filosofía.\n* Héctor Raúl Grenni, Editor, Doctor en Historia de América Latina.\n* Carlos Iván Orellana, Doctor en Ciencias Sociales.\n* Amparo Marroquín, Doctora en Filosofía.\n* Guillermo Gutiérrez, Doctor en Ciencias Empresariales.\n* Milton Ascencio, Doctor en Educación.\n\nEl **Comité Internacional de Pares Evaluadores** está integrado por:\n\n* José de La Fuente. Dr. en literatura, Universidad Católica Silva Henríquez, Chile.\n* Ricardo Salas Astraín, Universidad Católica Silva Henríquez, Santiago, Chile, Doctor en Filosofía.\n* Osvaldo Barreneche. Doctor en Historia, Universidad Nacional de La Plata, Argentina.\n* Marcelino Agís Villaverde. Doctor en Filosofía, Universidad Santiago de Compostela, España. \n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |','**Enfoque, políticas y alcances de Teoría y Praxis**\n\n**Teoría y Praxis** es una publicación en el ámbito de las Ciencias Sociales de la Universidad Don Bosco, El Salvador.  Recoge y ofrece a la comunidad académica la producción intelectual de la Universidad Don Bosco y de la comunidad académica en general.\n\n**Teoría y Praxis** quiere crear un espacio posible para la simbiosis entre la razón y la realidad, lo intelectual y lo integral y entre la teoría y la praxis. El objetivo primero es ofrecer un espacio académico abierto y plural que permita a los investigadores de diferentes procedencias y disciplinas de las Ciencias Sociales establecer un fructífero intercambio, plasmando así un lugar de discusión abierto y plural. Partiendo de la convicción de que los esfuerzos teóricos no deben estar lejos de la realidad, favorece la presentación de ideas y propuestas que expresen el esfuerzo por indagar acerca de la realidad y la vida humana, poniendo en relieve la relación de la humanidad con lo trascendente, con las  demás personas y con el context&#x6F;**.**\n\nEn este propósito, **Teoría y Praxis** abre sus páginas a trabajos elaborados por otros investigadores vinculados al ámbito de las Ciencias Sociales, buscando establecer con ellos un espacio fecundo  capaz de generar encuentros, diálogos y creaciones intelectuales.\n\n**Teoría y Praxis** presenta publicaciones inéditas y revisadas por pares evaluadores externos, y estará indexada en las bases de datos que sustenten su calidad académica. El proceso de revisión por pares está determinado y escrito, y se revisa anualmente. Los[ Criterios para la evaluación de artículos,](http://www.udb.edu.sv/editorial/docspdf/criterios_evaluacion_articulos_teor%C3%ADa_y_praxis.pdf \"Criterios para la evaluación de artículos\") accesibles en su página web, determinan este proceso. Un **Comité Internacional de Pares Evaluadores** da sustento a la calidad académica de las publicaciones.\n\n**Teoría y Praxis**  mantiene una política de acceso abierta y libre, por medio del Repositorio de la Universidad Don Bosco, en el cual se la puede encontrar sin restricciones desde su primer número.\n\nSi bien **Teoría y Praxis** asume la responsabilidad de la publicación de artículos académicos, la responsabilidad acerca de sus afirmaciones queda en los autores de los mismos. El idioma oficial de **Teoría y Praxis** es el castellano; sin embargo, el Comité de Redacción podrá autorizar la publicación de artículos en otro idioma.\n\nLas Normas de Presentación, publicadas en cada número y de libre acceso en el Repositorio de la Universidad Don Bosco, determinan las condiciones y los tiempos en que deben presentarse los artículos propuestos para su publicación.\n\n**Teoría y Praxis** lleva una política de respeto a los derechos de autor, y reconoce las autorías en forma explícita. Al respecto, se acoge a las condiciones de publicación de Creative Commons **Reconocimiento – CompartirIgual (by-sa)**.\n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |','**Normas para la presentación de artículos**\n\nLa publicación de cualquier material estará supeditada a la aprobación del editor o el Consejo Editorial de la revista atendiendo los requisitos de presentación que a continuación se detallan. El incumplimiento de las normas siguientes puede derivar en la devolución del artículo para ser corregido o en su rechazo definitivo:\n\n* Los artículos deben presentarse en el idioma oficial de la publicación que es el castellano. Serán enviados a través de la plataforma OJS de la revista. La revista publicará tres tipos de escritos:\n  * *Artículos*: reporte de investigaciones empíricas, con base en el formato IMRyD (Introducción, Método, Resultados y Discusión). También se incluyen en esta sección textos caracterizados por su complejidad, fundamentación o extensión cuya construcción descansa en una argumentación sustentada, amplia y sólida. La extensión de estos manuscritos deberá oscilar entre las 7000 y 9000 palabras incluyendo todas sus partes (título, resumen, tablas, referencias, etc.).\n  * *Ensayos*: trabajos de reflexión crítica de naturaleza teórica, filosófica, metodológica o a propósito de un fenómeno o coyuntura particular. A manera de orientación, su estructura debería contemplar al menos las siguientes secciones: introducción, desarrollo de la argumentación, conclusiones y referencias. No se aceptarán ensayos sin apartado de referencias. Su extensión oscilará entre 5000 y 7000 palabras.\n  * *Reseña de libros, películas o documentales*: recensiones de libros u obras fílmicas de interés para el campo de las Ciencias Sociales o las Humanidades. Las obras reseñadas deberán haber sido producidas en los tres años previos a la elaboración del escrito. La extensión de este tipo de escritos oscilará entre las 2000 y 3000 palabras.\n* Los distintos tipos de escritos deberán ser elaborados en formato de archivo Word, página tamaño carta a espacio simple con fuente Trebuchet MS, márgenes de 3 cm en todos sus costados. El título del trabajo debe usar un tamaño de fuente de 16, los subtítulos 14 y el texto del artículo tamaño 12.\n* En la primera página, luego del título en castellano (tamaño 16) deberá añadir el título en inglés (tamaño de fuente 14). Luego alineado a la derecha se debe colocar el nombre del o los (las) autores (as) en líneas separadas. En pie de página se deberá indicar para cada autor sus datos de identificación académica, usualmente estos incluyen aspectos como los siguientes: nacionalidad, título o cargo principal, adscripción institucional, número ORCID y dirección de correo electrónico.\n* Después del nombre de los autores, en tamaño de fuente 10, se colocará un resumen en castellano y en inglés (abstract) seguidos, respectivamente, en castellano e inglés, de cinco palabras o conceptos clave (keywords) de identificación de contenido. El resumen deberá tener una extensión de entre 200 y 250 palabras.\n* Las tablas, cuadros gráficos y figuras deberán titularse debidamente y contar con llamados en el texto. Se colocarán en el texto en el lugar en el que corresponden. Estos recursos visuales deben ser estéticos y sobrios (la revista se imprime en blanco y negro) y las tablas y cuadros deben prescindir de líneas internas innecesarias. Es responsabilidad de los autores contar con los permisos necesarios en caso de utilizar material protegido con algún tipo de propiedad intelectual.\n* La gestión de fuentes al interior del texto y en el apartado de referencias responderá al formato APA 7a. edición. Se solicita evitar o reducir al máximo posible el uso de notas al pie de página.\n\nLas colaboraciones deberán ser enviadas en un archivo de cualquier versión de Word a:\n\n**Carlos Iván Orellana**\n\nUniversidad Don Bosco, El Salvador\n\n[ivan.orellana@udb.edu.sv](mailto:ivan.orellana@udb.edu.sv)\n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |','**Proceso para la aceptación de artículos** \n\nEste proceso sirve como instrumento de medición para procurar la máxima objetividad y transparencia en la evaluación de los artículos que son presentados para ser publicados en Teoría y Praxis.\n\n* La recepción de los artículos está a cargo del Editor del Consejo Editorial, quien evalúa sus aspectos formales, su pertinencia al ámbito de las Ciencias Sociales y su apego a las **Normas para la presentación de artículos**, y lo presenta al Consejo Editorial. Éste podrá devolverlo a su autor con indicaciones que considere necesarias.\n* Una vez aceptado, el artículo es enviado a dos pares evaluadores miembros del Comité de Pares Evaluadores, los que emitirán juico acerca de la relevancia de la problemática, la claridad del encuadre teórico, la consistencia lógica y el sustento de los argumentos.\n* Finalmente, el Comité Editorial decide acerca de su publicación, y basará su decisión en los informes de los Pares Evaluadores y en las prioridades de publicación.\n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |','**Carlos Iván Orellana**\n\nDirección de Postgrados en Ciencias Sociales.\n\nUniversidad Don Bosco, Campus Antiguo Cuscatlán. Colonia Jardines de Guadalupe. La Libertad, El Salvador.\n\nTel. +503 2251-8200\n\n[**ivan.orellana@udb.edu.sv**](mailto:ivan.orellana@udb.edu.sv)\n\n| Publicada en:                                                                                                                                                | Revistas Consorciadas:                                                                                                                                       |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"108\" width=\"228\" alt=\"ebsco\" title=\"EBSCO\" src=\"http://localhost:8080/editorial/api/public/imagescontent/ebsco_1775015036_69cc947ce764e.jpg\" /> | <img height=\"111\" width=\"228\" alt=\"Retos\" title=\"Retos\" src=\"http://localhost:8080/editorial/api/public/imagescontent/retos_1775015331_69cc95a33e4f4.jpg\" /> |\n\n| Indexada en:                                                                                                                                                                                                                                                                                                                         |\n| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| <img height=\"104\" width=\"219\" alt=\"Latindex\" title=\"Latindex\" src=\"http://localhost:8080/editorial/api/public/imagescontent/latindex_1775015432_69cc96088da44.jpg\" /><img height=\"102\" width=\"215\" alt=\"CAMJOL\" title=\"camjol\" src=\"http://localhost:8080/editorial/api/public/imagescontent/camjol_1775015447_69cc96178b7c6.jpg\" /> |',4,1),(3,'esto es nuevoooaaaaaaaa asies\n\n![](http://localhost:8080/editorial/api/public/imagescontent/73725512_1775099128_69cddcf847cef.jpg)',NULL,NULL,NULL,NULL,NULL,3,1);
