--
-- Table structure for table `publishings`
--

DROP TABLE IF EXISTS `publishings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `publishings` (
  `idPublishing` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(300) DEFAULT NULL,
  `cover` varchar(150) DEFAULT NULL,
  `age` varchar(150) DEFAULT NULL,
  `volume` int(11) DEFAULT NULL,
  `volume_date` date DEFAULT NULL,
  `publish_code` varchar(50) DEFAULT NULL,
  `is_new_arrival` tinyint(1) DEFAULT NULL,
  `publish_date` date DEFAULT NULL,
  `publisher` varchar(100) DEFAULT NULL,
  `stock` int(11) DEFAULT NULL,
  `language_id` int(11) DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `publishing_type` int(11) DEFAULT NULL,
  `age_number` int(11) DEFAULT NULL COMMENT 'numero de epoca',
  `pages` int(11) DEFAULT NULL COMMENT 'numero de paginas de la publicacion',
  `URL` text COMMENT 'URL generada a partir del titulo',
  `state` tinyint(4) NOT NULL DEFAULT '1' COMMENT 'Campo que permite evaluar si una publicacion esta activa o no',
  `resource_URL` text COMMENT 'URL de acceso al recurso del repositorio',
  PRIMARY KEY (`idPublishing`),
  KEY `language_id` (`language_id`),
  KEY `category_id` (`category_id`),
  KEY `publishing_type` (`publishing_type`),
  CONSTRAINT `publishings_ibfk_1` FOREIGN KEY (`language_id`) REFERENCES `languages` (`idLanguage`),
  CONSTRAINT `publishings_ibfk_2` FOREIGN KEY (`category_id`) REFERENCES `categories` (`idCategory`),
  CONSTRAINT `publishings_ibfk_3` FOREIGN KEY (`publishing_type`) REFERENCES `publishing_types` (`idPublishingType`)
) ENGINE=InnoDB AUTO_INCREMENT=336 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `publishings`
--

